command:
$ErrorActionPreference = 'Stop'
$expectedHead = 'f86e94f77ea0dbe20a984d5d7ece29665c8ec468'
$branch = 'issue-398-gemini-architecture-hardening'
function Invoke-Checked([string]$Label, [scriptblock]$Action) {
  Write-Host "=== $Label ==="
  & $Action
  if ($LASTEXITCODE -ne 0) { throw "$Label failed with exit $LASTEXITCODE" }
}
git fetch --no-tags origin $branch main
if ($LASTEXITCODE -ne 0) { throw 'Unable to fetch issue #398 branch/main' }
if ((git rev-parse "origin/$branch").Trim() -ne $expectedHead) { throw 'Issue #398 branch head moved before governed package refresh' }
git checkout -B $branch $expectedHead
if ($LASTEXITCODE -ne 0) { throw 'Unable to checkout issue #398 branch head' }
Invoke-Checked 'Behavior adapter materialization check before package refresh' { python project_sources/agent_runtime/tools/materialize_agent_behavior_adapters.py --check }
Invoke-Checked 'Materialize OpenAI DCOIR package' { python project_sources/agent_runtime/tools/build_openai_dcoir_analyst.py --materialize }
Invoke-Checked 'Materialize OpenAI USB package' { python project_sources/agent_runtime/tools/build_openai_usb_reporting.py --materialize }
$changed = @(git diff --name-only)
$allowed = @(
  'project_sources/agent_runtime/generated/packages/openai_dcoir_analyst/manifest.json',
  'project_sources/agent_runtime/generated/packages/openai_usb_reporting/manifest.json'
)
$unexpected = @($changed | Where-Object { $_ -notin $allowed })
if ($unexpected.Count -gt 0) { $unexpected | Out-Host; throw 'Package materialization changed files outside the two expected generated manifests' }
if ($changed.Count -eq 0) { throw 'Package materialization produced no generated drift repair' }
Write-Host 'materialized_changed_files:'
$changed | ForEach-Object { Write-Host "- $_" }
Invoke-Checked '1 Shared source contract' { python project_sources/agent_runtime/tools/validate_shared_agent_source_contract.py }
Invoke-Checked '2 Shared source contract self-tests' { python project_sources/agent_runtime/tests/validate_shared_agent_source_contract_selftest.py }
Invoke-Checked '3 Behavior adapter materialization check' { python project_sources/agent_runtime/tools/materialize_agent_behavior_adapters.py --check }
Invoke-Checked '4 Behavior adapter self-tests' { python project_sources/agent_runtime/tests/materialize_agent_behavior_adapters_selftest.py }
Invoke-Checked '5 Knowledge projection check' { python project_sources/agent_runtime/tools/project_agent_knowledge.py --check }
Invoke-Checked '6 Knowledge projection self-tests' { python project_sources/agent_runtime/tests/project_agent_knowledge_selftest.py }
Invoke-Checked '7 OpenAI DCOIR package check' { python project_sources/agent_runtime/tools/build_openai_dcoir_analyst.py --check }
Invoke-Checked '8 OpenAI DCOIR package self-tests' { python project_sources/agent_runtime/tests/build_openai_dcoir_analyst_selftest.py }
Invoke-Checked '9 OpenAI USB package check' { python project_sources/agent_runtime/tools/build_openai_usb_reporting.py --check }
Invoke-Checked '10 OpenAI USB package self-tests' { python project_sources/agent_runtime/tests/build_openai_usb_reporting_selftest.py }
git add project_sources/agent_runtime/generated/packages/openai_dcoir_analyst/manifest.json project_sources/agent_runtime/generated/packages/openai_usb_reporting/manifest.json
git diff --cached --quiet
if ($LASTEXITCODE -eq 0) { throw 'Expected generated manifest repairs were not staged' }
git -c user.name='Malware Devil' -c user.email='34285973+malwaredevil@users.noreply.github.com' commit -m 'Refresh cross-provider package manifests for #398'
if ($LASTEXITCODE -ne 0) { throw 'Unable to commit #398 generated manifest refresh' }
$newHead = (git rev-parse HEAD).Trim()
Write-Host "new_branch_head=$newHead"
Invoke-Checked 'Exact-head unified release parity' { python project_sources/agent_runtime/tools/report_agent_release_parity.py --source-commit $newHead --output-root project_sources/validation/out_issue398_agent_runtime_parity }
$tracked = git status --porcelain --untracked-files=no
if ($LASTEXITCODE -ne 0) { throw 'Unable to inspect tracked state after validation' }
if ($tracked) { $tracked | Out-Host; throw 'Validation changed tracked files after commit' }
git push origin HEAD:$branch
if ($LASTEXITCODE -ne 0) { throw 'Unable to push refreshed #398 branch' }
Write-Host "ISSUE398_PACKAGE_REFRESH_COMPLETE head=$newHead"
